WITH seed(discipline_name,topic_name,position,title,content) AS (VALUES ('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',1,'Conceito central','O ensino de Língua Portuguesa nos anos iniciais articula oralidade, leitura, produção de textos e reflexão sobre a linguagem em situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',2,'Pergunta orientadora','O que muda na prática quando práticas de oralidade, leitura e escrita é tratado como aprendizagem situada em práticas de linguagem?'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',3,'Elementos fundamentais','Considere objetivo, contexto, gênero, interlocutores, atividade, mediação e evidências ao analisar práticas de oralidade, leitura e escrita.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',4,'Exemplo para visualizar','Uma turma realiza uma atividade concreta de linguagem relacionada a práticas de oralidade, leitura e escrita e depois explica as escolhas que fez.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',5,'Situação para analisar','Identifique em um caso quais conhecimentos de práticas de oralidade, leitura e escrita estão envolvidos e quais evidências demonstrariam avanço.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',6,'Erro comum','Reduzir práticas de oralidade, leitura e escrita a exercícios mecânicos, sem finalidade comunicativa nem relação com práticas reais de linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',7,'Aprofundamento','A BNCC articula leitura, escrita, oralidade e análise linguística e orienta sua progressão por práticas e situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',8,'Aplicação pedagógica','Planeje uma atividade em que práticas de oralidade, leitura e escrita tenha finalidade clara, destinatário definido e espaço para revisão ou reflexão.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',9,'Síntese','O ensino de Língua Portuguesa nos anos iniciais articula oralidade, leitura, produção de textos e reflexão sobre a linguagem em situações de uso. O domínio envolve compreensão conceitual e uso em situações concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Práticas de oralidade, leitura e escrita',10,'Para revisar','Explique práticas de oralidade, leitura e escrita com palavras próprias e dê um exemplo de atividade que produza uma evidência de aprendizagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',1,'Conceito central','A alfabetização envolve apropriação progressiva do sistema de escrita alfabética em articulação com práticas significativas de leitura e escrita.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',2,'Pergunta orientadora','O que muda na prática quando alfabetização e apropriação da linguagem é tratado como aprendizagem situada em práticas de linguagem?'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',3,'Elementos fundamentais','Considere objetivo, contexto, gênero, interlocutores, atividade, mediação e evidências ao analisar alfabetização e apropriação da linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',4,'Exemplo para visualizar','Uma turma realiza uma atividade concreta de linguagem relacionada a alfabetização e apropriação da linguagem e depois explica as escolhas que fez.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',5,'Situação para analisar','Identifique em um caso quais conhecimentos de alfabetização e apropriação da linguagem estão envolvidos e quais evidências demonstrariam avanço.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',6,'Erro comum','Reduzir alfabetização e apropriação da linguagem a exercícios mecânicos, sem finalidade comunicativa nem relação com práticas reais de linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',7,'Aprofundamento','A BNCC articula leitura, escrita, oralidade e análise linguística e orienta sua progressão por práticas e situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',8,'Aplicação pedagógica','Planeje uma atividade em que alfabetização e apropriação da linguagem tenha finalidade clara, destinatário definido e espaço para revisão ou reflexão.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',9,'Síntese','A alfabetização envolve apropriação progressiva do sistema de escrita alfabética em articulação com práticas significativas de leitura e escrita. O domínio envolve compreensão conceitual e uso em situações concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Alfabetização e apropriação da linguagem',10,'Para revisar','Explique alfabetização e apropriação da linguagem com palavras próprias e dê um exemplo de atividade que produza uma evidência de aprendizagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',1,'Conceito central','Produção textual envolve planejar, escrever, revisar e reescrever considerando finalidade, destinatário, gênero e conteúdo.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',2,'Pergunta orientadora','O que muda na prática quando produção e revisão de textos é tratado como aprendizagem situada em práticas de linguagem?'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',3,'Elementos fundamentais','Considere objetivo, contexto, gênero, interlocutores, atividade, mediação e evidências ao analisar produção e revisão de textos.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',4,'Exemplo para visualizar','Uma turma realiza uma atividade concreta de linguagem relacionada a produção e revisão de textos e depois explica as escolhas que fez.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',5,'Situação para analisar','Identifique em um caso quais conhecimentos de produção e revisão de textos estão envolvidos e quais evidências demonstrariam avanço.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',6,'Erro comum','Reduzir produção e revisão de textos a exercícios mecânicos, sem finalidade comunicativa nem relação com práticas reais de linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',7,'Aprofundamento','A BNCC articula leitura, escrita, oralidade e análise linguística e orienta sua progressão por práticas e situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',8,'Aplicação pedagógica','Planeje uma atividade em que produção e revisão de textos tenha finalidade clara, destinatário definido e espaço para revisão ou reflexão.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',9,'Síntese','Produção textual envolve planejar, escrever, revisar e reescrever considerando finalidade, destinatário, gênero e conteúdo. O domínio envolve compreensão conceitual e uso em situações concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Produção e revisão de textos',10,'Para revisar','Explique produção e revisão de textos com palavras próprias e dê um exemplo de atividade que produza uma evidência de aprendizagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',1,'Conceito central','Análise linguística envolve observar e refletir sobre escolhas de linguagem, funcionamento das palavras e frases e convenções de escrita a partir de práticas concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',2,'Pergunta orientadora','O que muda na prática quando análise linguística nos anos iniciais é tratado como aprendizagem situada em práticas de linguagem?'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',3,'Elementos fundamentais','Considere objetivo, contexto, gênero, interlocutores, atividade, mediação e evidências ao analisar análise linguística nos anos iniciais.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',4,'Exemplo para visualizar','Uma turma realiza uma atividade concreta de linguagem relacionada a análise linguística nos anos iniciais e depois explica as escolhas que fez.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',5,'Situação para analisar','Identifique em um caso quais conhecimentos de análise linguística nos anos iniciais estão envolvidos e quais evidências demonstrariam avanço.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',6,'Erro comum','Reduzir análise linguística nos anos iniciais a exercícios mecânicos, sem finalidade comunicativa nem relação com práticas reais de linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',7,'Aprofundamento','A BNCC articula leitura, escrita, oralidade e análise linguística e orienta sua progressão por práticas e situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',8,'Aplicação pedagógica','Planeje uma atividade em que análise linguística nos anos iniciais tenha finalidade clara, destinatário definido e espaço para revisão ou reflexão.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',9,'Síntese','Análise linguística envolve observar e refletir sobre escolhas de linguagem, funcionamento das palavras e frases e convenções de escrita a partir de práticas concretas. O domínio envolve compreensão conceitual e uso em situações concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Análise linguística nos anos iniciais',10,'Para revisar','Explique análise linguística nos anos iniciais com palavras próprias e dê um exemplo de atividade que produza uma evidência de aprendizagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',1,'Conceito central','Planejar Língua Portuguesa exige definir práticas de linguagem, gêneros, objetivos, atividades e evidências de aprendizagem de maneira articulada.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',2,'Pergunta orientadora','O que muda na prática quando planejamento e avaliação em língua portuguesa é tratado como aprendizagem situada em práticas de linguagem?'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',3,'Elementos fundamentais','Considere objetivo, contexto, gênero, interlocutores, atividade, mediação e evidências ao analisar planejamento e avaliação em língua portuguesa.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',4,'Exemplo para visualizar','Uma turma realiza uma atividade concreta de linguagem relacionada a planejamento e avaliação em língua portuguesa e depois explica as escolhas que fez.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',5,'Situação para analisar','Identifique em um caso quais conhecimentos de planejamento e avaliação em língua portuguesa estão envolvidos e quais evidências demonstrariam avanço.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',6,'Erro comum','Reduzir planejamento e avaliação em língua portuguesa a exercícios mecânicos, sem finalidade comunicativa nem relação com práticas reais de linguagem.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',7,'Aprofundamento','A BNCC articula leitura, escrita, oralidade e análise linguística e orienta sua progressão por práticas e situações de uso.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',8,'Aplicação pedagógica','Planeje uma atividade em que planejamento e avaliação em língua portuguesa tenha finalidade clara, destinatário definido e espaço para revisão ou reflexão.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',9,'Síntese','Planejar Língua Portuguesa exige definir práticas de linguagem, gêneros, objetivos, atividades e evidências de aprendizagem de maneira articulada. O domínio envolve compreensão conceitual e uso em situações concretas.'),('Ensino de Língua Portuguesa nos Anos Iniciais','Planejamento e avaliação em Língua Portuguesa',10,'Para revisar','Explique planejamento e avaliação em língua portuguesa com palavras próprias e dê um exemplo de atividade que produza uma evidência de aprendizagem.'))
UPDATE public.material_sections ms SET title=s.title,content=s.content,section_type=
CASE s.position WHEN 1 THEN 'concept' WHEN 2 THEN 'explanation' WHEN 3 THEN 'explanation' WHEN 4 THEN 'examples'
WHEN 5 THEN 'examples' WHEN 6 THEN 'common_mistakes' WHEN 7 THEN 'deepening' WHEN 8 THEN 'deepening'
WHEN 9 THEN 'review' ELSE 'review' END
FROM seed s,public.materials m,public.topics t,public.disciplines d
WHERE ms.material_id=m.id AND m.topic_id=t.id AND t.discipline_id=d.id
AND d.name=s.discipline_name AND t.name=s.topic_name AND ms.position=s.position AND m.status='draft';